      "expect": "stable /search n=2273 slow>200ms=0 max=193"
    },
    {
      "claim": "Canary /search p99 is >=600ms while stable /search p99 is <=100ms, yet their p50 and p95 agree within 2ms.",
      "query": "const q=(a,p)=>{const s=a.slice().sort((x,y)=>x-y); return s[Math.min(s.length-1,Math.ceil(p*s.length)-1)];}; const c=canary.filter(r=>r.path==='/search').map(r=>r.ms), s=stable.filter(r=>r.path==='/search').map(r=>r.ms); const cp50=q(c,0.5),cp95=q(c,0.95),cp99=q(c,0.99),sp50=q(s,0.5),sp95=q(s,0.95),sp99=q(s,0.99); print('canary /search p50='+cp50+' p95='+cp95+' p99='+cp99); print('stable /search p50='+sp50+' p95='+sp95+' p99='+sp99); print('canary p99>=600: '+(cp99>=600)+' | stable p99<=100: '+(sp99<=100)+' | p50 gap<=2ms: '+(Math.abs(cp50-sp50)<=2)+' | p95 gap<=2ms: '+(Math.abs(cp95-sp95)<=2));",
      "expect": "canary p99>=600: true | stable p99<=100: true | p50 gap<=2ms: true | p95 gap<=2ms: true"
    },
    {
      "claim": "The 18 slow canary /search requests are spread across all four 30s windows of the 120s test, so they are not a startup/warmup artifact.",
      "query": "const slow=canary.filter(r=>r.path==='/search'&&r.ms>=600); const w=[0,0,0,0]; slow.forEach(r=>{w[Math.min(3,Math.floor(r.t/30))]++;}); print('canary /search >=600ms per 30s window: '+w.join(',')); print('windows with >=1 slow: '+w.filter(x=>x>0).length+'/4 total='+slow.length);",
      "expect": "windows with >=1 slow: 4/4 total=18"
    },
    {
      "claim": "The slow tail is confined to /search: canary has 0 /browse and 1 /checkout request over 200ms, versus stable 0 and 7.",
      "query": "const n=(v,p)=>v.filter(r=>r.path===p&&r.ms>200).length; print('non-search slow>200ms: canary /browse='+n(canary,'/browse')+' /checkout='+n(canary,'/checkout')+' ; stable /browse='+n(stable,'/browse')+' /checkout='+n(stable,'/checkout'));",
      "expect": "non-search slow>200ms: canary /browse=0 /checkout=1 ; stable /browse=0 /checkout=7"
