      "claim": "Neither version returned any 5xx or any non-200 response during the test.",
      "query": "const f=a=>({n:a.length,x5:a.filter(r=>r.status>=500).length,nb:a.filter(r=>r.status!==200).length}); const c=f(canary), s=f(stable); print('canary n='+c.n+' 5xx='+c.x5+' non200='+c.nb); print('stable n='+s.n+' 5xx='+s.x5+' non200='+s.nb); print('zero errors both versions: '+(c.x5===0&&s.x5===0&&c.nb===0&&s.nb===0));",
